const notes = new Map();
let counter = 0;

function nextId() {
  counter += 1;
  return `n${counter}`;
}

export async function listTools() {
  return [
    {
      name: 'note_create',
      description: 'Create a note with a title and body.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'Note title (non-empty).' },
          body: { type: 'string', description: 'Note body (non-empty).' }
        },
        required: ['title', 'body']
      }
    },
    {
      name: 'note_get',
      description: 'Get a note by its id.',
      inputSchema: {
        type: 'object',
        properties: {
          note_id: { type: 'string', description: 'The id of the note to retrieve.' }
        },
        required: ['note_id']
      }
    }
  ];
}

function isNonEmptyString(value) {
  return typeof value === 'string' && value.length > 0;
}

export async function callTool(name, args) {
  if (name === 'note_create') {
    if (!isNonEmptyString(args.title)) throw new Error('title is required and must be a non-empty string');
    if (!isNonEmptyString(args.body)) throw new Error('body is required and must be a non-empty string');
    const id = nextId();
    notes.set(id, { id, title: args.title, body: args.body });
    return { content: [{ type: 'text', text: `Created note ${id}: ${args.title}` }] };
  }
  if (name === 'note_get') {
    if (!isNonEmptyString(args.note_id)) throw new Error('note_id is required and must be a non-empty string');
    const note = notes.get(args.note_id);
    if (!note) throw new Error(`note not found: ${args.note_id}`);
    return { content: [{ type: 'text', text: `${note.title}\n${note.body}\n(id: ${note.id})` }] };
  }
  throw new Error(`unknown tool: ${name}`);
}
